import calendarclass Month:    def __init__(self, y, m):        self.y = y        self.m = m    def show(self):        print(calendar.month(self.y, self.m))class Year:    def __init__(self, y):        self.y = y    def show_all(self):        for m in range(1, 13):            print(calendar.month(self.y, m))# Как пользоваться:m = Month(2025, 5)m.show()y = Year(2025)y.show_all()